diff --git a/src/cli.ts b/src/cli.ts
--- a/src/cli.ts
+++ b/src/cli.ts
@@ -61,28 +61,30 @@ export async function main(argv: string[], cli: CliEnv): Promise<number> {
   const guarded = (inner: Transcript): Transcript => {
     guard = {
       begin: async (kind) => {
         begun = true
         try {
           await inner.begin(kind)
         } catch (error) {
           begun = false
           throw error
         }
       },
       answerKeys: (questions) => inner.answerKeys(questions),
       result: (index, result) => inner.result(index, result),
       passed: async (score, notQuizzedChunks) => {
+        // A reply that lands after Ctrl-C must not pass the run that was reported as stopped.
+        if (closed) throw new MuellimError('aborted')
         closed = true
         try {
           await inner.passed(score, notQuizzedChunks)
         } catch (error) {
           closed = false
           throw error
         }
       },
       abandoned: async () => {
         if (closed) return
         closed = true
         await inner.abandoned()
       },
     }
